def select_grasp_for_pulling(grasps: np.ndarray, scores: np.ndarray, pull_direction: np.ndarray, vertical_fingers: bool, world_from_grasp_frame: np.ndarray | None = None) -> tuple[np.ndarray | None, float]:
    import numpy as np
    pull_dir = np.array(pull_direction, dtype=float)
    norm = np.linalg.norm(pull_dir)
    if norm > 0:
        pull_dir = pull_dir / norm
    best_grasp = None
    best_score = -float('inf')
    yaw_mat = np.eye(4)
    yaw_mat[:3, :3] = np.array([[0, -1, 0], [1, 0, 0], [0, 0, 1]])
    for g, s in zip(grasps, scores):
        g_world = world_from_grasp_frame @ g if world_from_grasp_frame is not None else g
        approach_axis = g_world[:3, 2]
        if np.dot(approach_axis, pull_dir) < -0.5:
            if abs(pull_dir[2]) < 0.5 and abs(approach_axis[2]) > 0.6:
                continue
            z_comp_x = abs(g_world[2, 0])
            z_comp_y = abs(g_world[2, 1])
            if vertical_fingers:
                if z_comp_x > z_comp_y:
                    if z_comp_x > 0.5 and s > best_score:
                        best_score, best_grasp = s, g_world
                else:
                    if z_comp_y > 0.5 and s > best_score:
                        best_score, best_grasp = s, g_world @ yaw_mat
            else:
                if z_comp_x < z_comp_y:
                    if z_comp_x < 0.5 and s > best_score:
                        best_score, best_grasp = s, g_world
                else:
                    if z_comp_y < 0.5 and s > best_score:
                        best_score, best_grasp = s, g_world @ yaw_mat
    return best_grasp, best_score

def push_surface_inward(target_pos: np.ndarray, pull_dir: np.ndarray, push_distance: float = 0.10, approach_distance: float = 0.15) -> bool:
    R_top_down = np.array([
        [1, 0, 0],
        [0, -1, 0],
        [0, 0, -1]
    ])
    quat = rotation_matrix_to_quaternion(R_top_down)
    close_gripper()
    start_pos = target_pos + approach_distance * pull_dir
    push_pos = target_pos - push_distance * pull_dir
    goto_pose(start_pos, quat)
    try:
        goto_pose(push_pos, quat)
    except Exception:
        pass
    try:
        goto_pose(start_pos, quat)
    except Exception:
        pass
    return True

def push_object_closed(object_name: str, push_distance: float = 0.15, approach_distance: float = 0.15) -> bool:
    pos = localize_object_with_molmo_sam3(object_name)
    if pos is None:
        return False
    pull_dir = get_axis_aligned_pull_direction(pos)
    if pull_dir is None:
        return False
    close_gripper()
    return push_surface_inward(pos, pull_dir, push_distance=push_distance, approach_distance=approach_distance)

def compute_horizontal_pull_direction_towards_base(object_pos: np.ndarray, robot_base_pos: np.ndarray) -> np.ndarray:
    pull_direction = robot_base_pos[:3] - object_pos[:3]
    pull_direction[2] = 0.0
    return normalize_vector(pull_direction)

def get_highest_scoring_grasp(grasps: np.ndarray, scores: np.ndarray, apply_grasp_yaw: bool = True) -> np.ndarray:
    if len(grasps) == 0:
        return None
    best_idx = np.argmax(scores)
    best_grasp = grasps[best_idx].copy()
    if apply_grasp_yaw:
        yaw_mat = np.eye(4)
        yaw_mat[:3, :3] = np.array([[0, -1, 0], [1, 0, 0], [0, 0, 1]])
        best_grasp = best_grasp @ yaw_mat
    return best_grasp

def filter_grasps_by_approach_axis(grasps: np.ndarray, scores: np.ndarray, desired_approach_axis: np.ndarray, angle_threshold_deg: float = 45.0) -> tuple[np.ndarray, np.ndarray]:
    import numpy as np
    desired_axis = np.array(desired_approach_axis, dtype=float)
    norm = np.linalg.norm(desired_axis)
    if norm == 0:
        return np.array([]), np.array([])
    desired_axis /= norm
    cos_threshold = np.cos(np.radians(angle_threshold_deg))
    valid_indices = []
    for i, g in enumerate(grasps):
        approach_axis = g[:3, 2]
        app_norm = np.linalg.norm(approach_axis)
        if app_norm > 0:
            approach_axis = approach_axis / app_norm
            if np.dot(approach_axis, desired_axis) >= cos_threshold:
                valid_indices.append(i)
    if not valid_indices:
        return np.array([]), np.array([])
    return grasps[valid_indices], scores[valid_indices]

def localize_and_push_object_away(object_name: str, push_distance: float = 0.10, pre_push_offset: float = 0.08, z_offset: float = 0.06) -> dict:
    """Localize an object and push it away from the robot base."""
    pc_segment = localize_and_verify_object_point_cloud(object_name)
    if pc_segment is None or len(pc_segment) == 0:
        return {"success": False, "reason": "localization_failed"}
    close_gripper()
    push_res = push_point_cloud_away_from_base(pc_segment, push_distance=push_distance, pre_push_offset=pre_push_offset, z_offset=z_offset)
    return {"success": True, "push_result": push_res, "num_points": len(pc_segment)}
